// Ngưỡng Core Web Vitals (web.dev): [tốt, cần cải thiện]
const T = { LCP: [2500, 4000], INP: [200, 500], CLS: [0.1, 0.25] };

function rate(metric, value) {
  const [good, ni] = T[metric];
  return value <= good ? "tốt" : value <= ni ? "cần cải thiện" : "kém";
}

console.log(rate("LCP", 2100), rate("LCP", 3000), rate("LCP", 5000));
console.log(rate("CLS", 0.05), rate("INP", 350));

