const T = { LCP: [2500, 4000], CLS: [0.1, 0.25], INP: [200, 500] };
function rate(metric, value) {
  const [g, n] = T[metric];
  return value <= g ? "good" : value <= n ? "ni" : "poor";
}
const cases = [["LCP", 2400], ["LCP", 4001], ["CLS", 0.1], ["CLS", 0.3], ["INP", 200], ["INP", 501]];
console.log(cases.map(([m, v]) => rate(m, v)).join(","));

